package com.dronelink.app.drone

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Byte-compare the Kotlin engine against the Python oracle.
 * Expected bytes below were generated by running the REAL oracle
 * (drone-ctl/drone_daemon.py Drone class) on 2026-11-18:
 *
 *   Python: d = Drone(force_variant=10); d.axes = (C,C,0,C); d.packet().hex(' ')
 *
 * Any drift in these bytes means the port broke the drone's wire contract.
 */
class DroneEngineTest {

    /** Records sent bytes; receive always times out (-1). */
    private class RecordingTransport : DroneTransport {
        val sent = mutableListOf<ByteArray>()
        var cannedReceive: ByteArray? = null
        var bindCalls = 0
        override fun bind() { bindCalls++ }
        override fun send(data: ByteArray) { sent += data }
        override fun receive(buf: ByteArray): Int {
            val canned = cannedReceive ?: return -1
            canned.copyInto(buf)
            return canned.size
        }

        override fun probeSend(destPort: Int, srcPort: Int, data: ByteArray): List<String> = emptyList()
        override fun close() {}
    }

    private fun engine(forceVariant: Int? = null, transport: RecordingTransport = RecordingTransport()): Pair<DroneEngine, RecordingTransport> =
        DroneEngine(transport, forceVariant) to transport

    private fun hex(bytes: ByteArray): String = bytes.joinToString(" ") { "%02x".format(it) }

    // ---- TC (9-byte) packets ----

    @Test fun tcNeutral() {
        val (d, _) = engine(10)
        d.axes = intArrayOf(DroneProtocol.C, DroneProtocol.C, 0, DroneProtocol.C)
        assertEquals("03 66 80 80 00 80 00 80 99", hex(d.packet()))
    }

    @Test fun tcTakeoff() {
        val (d, _) = engine(10)
        d.axes = intArrayOf(DroneProtocol.C, DroneProtocol.C, 0, DroneProtocol.C)
        d.pulse("takeoff", 1.0)
        // v0.3.1: takeoff sends throttle with the flag (flag alone doesn't lift)
        assertEquals("03 66 80 80 3c 80 01 bd 99", hex(d.packet()))
    }

    @Test fun tcHeadless() {
        val (d, _) = engine(10)
        d.headless = true
        d.axes = intArrayOf(DroneProtocol.C, DroneProtocol.C, 0, DroneProtocol.C)
        assertEquals("03 66 80 80 00 80 10 90 99", hex(d.packet()))
    }

    @Test fun tcLand() {
        val (d, _) = engine(10)
        d.pulse("land", 1.0)
        d.axes = intArrayOf(128, 128, 0, 128)
        assertEquals("03 66 80 80 00 80 02 82 99", hex(d.packet()))
    }

    @Test fun tcCalibrateHeadless() {
        val (d, _) = engine(10)
        d.pulse("gyro", 2.0)
        d.headless = true
        d.axes = intArrayOf(128, 128, 0, 128)
        assertEquals("03 66 80 80 00 80 90 10 99", hex(d.packet()))
    }

    @Test fun tcSticks() {
        val (d, _) = engine(10)
        d.axes = intArrayOf(208, 68, 51, 153)  // oracle: set_sticks(0.5,-0.5,0.4,0.2) @ gear1
        assertEquals("03 66 d0 44 33 99 00 3e 99", hex(d.packet()))
    }

    @Test fun tcZeroClamp() {
        val (d, _) = engine(10)
        d.axes = intArrayOf(0, 0, 0, 0)  // roll/pitch/yaw clamped to 1, throttle stays 0
        assertEquals("03 66 01 01 00 01 00 01 99", hex(d.packet()))
    }

    // ---- GL (21-byte) packets ----

    @Test fun gl82Headless() {
        val (d, _) = engine(82)
        d.axes = intArrayOf(200, 60, 150, 100)
        d.headless = true
        assertEquals("03 66 14 c8 3c 96 64 00 03 00 00 00 00 00 00 00 00 00 00 05 99", hex(d.packet()))
    }

    @Test fun gl82Neutral() {
        val (d, _) = engine(82)
        d.axes = intArrayOf(128, 128, 0, 128)
        assertEquals("03 66 14 80 80 00 80 00 02 00 00 00 00 00 00 00 00 00 00 82 99", hex(d.packet()))
    }

    @Test fun gl82Takeoff() {
        val (d, _) = engine(82)
        d.pulse("takeoff", 1.0)
        d.axes = intArrayOf(128, 128, 0, 128)
        assertEquals("03 66 14 80 80 00 80 01 02 00 00 00 00 00 00 00 00 00 00 83 99", hex(d.packet()))
    }

    @Test fun gl82CalibrateHeadless() {
        val (d, _) = engine(82)
        d.pulse("gyro", 2.0)
        d.headless = true
        d.axes = intArrayOf(128, 128, 0, 128)
        assertEquals("03 66 14 80 80 00 80 04 03 00 00 00 00 00 00 00 00 00 00 87 99", hex(d.packet()))
    }

    @Test fun gl85Sticks() {
        val (d, _) = engine(85)
        d.axes = intArrayOf(200, 60, 150, 100)
        assertEquals("03 66 14 c8 3c 96 64 00 02 00 00 00 00 00 00 00 00 00 00 04 99", hex(d.packet()))
    }

    @Test fun gl90Neutral() {
        val (d, _) = engine(90)
        d.axes = intArrayOf(128, 128, 0, 128)
        assertEquals("03 66 14 80 80 00 80 00 02 00 00 00 00 00 00 00 00 00 00 82 99", hex(d.packet()))
    }

    // ---- heartbeat ----

    @Test fun heartbeatBytes() {
        val (d, t) = engine(10)
        d.raw(byteArrayOf(0x01, 0x01))
        assertEquals("01 01", hex(t.sent.last()))
    }

    // ---- stick math (Python int() truncation) ----

    @Test fun sticksTruncation() {
        val (d, _) = engine(10)
        d.setSticks(0.5, -0.5, 0.4, 0.2)
        assertEquals(listOf(148, 108, 50, 153), d.axes.toList())
    }

    @Test fun sticksClamp() {
        val (d, _) = engine(10)
        d.setSticks(-0.999, 0.999, 0.999, -0.999)
        assertEquals(listOf(88, 167, 126, 1), d.axes.toList())
    }

    @Test fun setGearClamps() {
        val (d, _) = engine(10)
        d.setGearRaw(0); assertEquals(1, d.gear)
        d.setGearRaw(9); assertEquals(3, d.gear)
        d.setGearRaw(2); assertEquals(2, d.gear)
    }

    // ---- trajectory normalization ----

    @Test fun trajectoryNormGear2() {
        val (d, _) = engine(10)
        d.setGearRaw(2)
        d.setTrajectory(listOf(mapOf("roll" to 0.5, "pitch" to 0.0, "throttle" to 0.4, "yaw" to 0.0, "duration" to 1.0)))
        assertEquals(1, d.waypoints.size)
        val wp = d.waypoints[0]
        assertEquals(158, wp.roll); assertEquals(128, wp.pitch); assertEquals(50, wp.throttle); assertEquals(128, wp.yaw)
        assertEquals(1.0, wp.duration, 0.0001)
    }

    @Test fun trajectoryNormGear3() {
        val (d, _) = engine(10)
        d.setGearRaw(3)
        d.setTrajectory(listOf(mapOf("roll" to -1.0, "pitch" to 1.0, "throttle" to 1.0, "yaw" to -1.0, "duration" to 2.5)))
        val wp = d.waypoints[0]
        assertEquals(1, wp.roll); assertEquals(255, wp.pitch); assertEquals(127, wp.throttle); assertEquals(1, wp.yaw)
        assertEquals(2.5, wp.duration, 0.0001)
    }

    @Test fun trajectoryNormGear1() {
        val (d, _) = engine(10)
        d.setTrajectory(listOf(mapOf("roll" to 0.0, "pitch" to 0.0, "throttle" to 0.0, "yaw" to 0.0, "duration" to 1.0)))
        val wp = d.waypoints[0]
        assertEquals(128, wp.roll); assertEquals(128, wp.pitch); assertEquals(0, wp.throttle); assertEquals(128, wp.yaw)
    }

    // ---- dead-man ----

    @Test fun deadmanStale() {
        var clock = 100.0
        val d = DroneEngine(RecordingTransport(), 10) { clock }
        assertTrue(d.deadman())   // axesTs=0, clock far ahead -> stale
        d.setSticks(0.0, 0.0, 0.0, 0.0)  // axesTs = now
        assertFalse(d.deadman())
        clock = 100.5  // +0.5 > STALE 0.4
        assertTrue(d.deadman())
    }

    @Test fun deadmanTrajectoryOverrides() {
        var clock = 100.0
        val d = DroneEngine(RecordingTransport(), 10) { clock }
        d.setTrajectory(listOf(mapOf("roll" to 0.5, "pitch" to 0.0, "throttle" to 0.4, "yaw" to 0.0, "duration" to 1.0)))
        clock = 101.0
        assertFalse(d.deadman())  // waypoints active -> never dead-man
    }

    @Test fun deadmanLock() {
        var clock = 100.0
        val d = DroneEngine(RecordingTransport(), 10) { clock }
        d.lockUntil = 104.0
        clock = 102.0
        assertTrue(d.deadman())  // emergency-land lock
        clock = 104.5
        // lock expired; axesTs=0 is still stale -> dead-man stays on
        assertTrue(d.deadman())
        d.setSticks(0.0, 0.0, 0.0, 0.0)  // fresh input
        assertFalse(d.deadman())
    }

    // ---- trajectory advance ----

    @Test fun advanceTrajectoryRunsAndFinishes() {
        var clock = 100.0
        val d = DroneEngine(RecordingTransport(), 10) { clock }
        d.setGearRaw(2)
        d.setTrajectory(listOf(mapOf("roll" to 0.5, "pitch" to 0.0, "throttle" to 0.4, "yaw" to 0.0, "duration" to 1.0)))
        d.advanceTrajectory()
        assertEquals(listOf(158, 128, 50, 128), d.axes.toList())
        assertEquals(0, d.wpIndex)
        assertTrue(d.waypoints.isNotEmpty())
        clock = 101.5
        d.advanceTrajectory()
        assertEquals(listOf(128, 128, 0, 128), d.axes.toList())
        assertTrue(d.waypoints.isEmpty())
        assertEquals(0, d.wpIndex)
    }

    // ---- hover (altitude hold) ----

    @Test fun hoverSustainsTakeoffThrottle() {
        val d = DroneEngine(RecordingTransport(), 10) { 100.0 }
        d.hover = true
        val p = d.packet()
        assertEquals(3, p[0].toInt() and 0xff)
        assertEquals(0x66, p[1].toInt() and 0xff)
        // TC frame: [3, 0x66, roll, pitch, throttle, yaw, flags, cs, 0x99]
        assertEquals(DroneProtocol.HOVER_THROTTLE, p[4].toInt() and 0xff)
    }

    @Test fun hoverOffSendsNeutralThrottle() {
        val d = DroneEngine(RecordingTransport(), 10) { 100.0 }
        val p = d.packet()
        assertEquals(0, p[4].toInt() and 0xff)
    }

    @Test fun hoverYieldsToUserStick() {
        val d = DroneEngine(RecordingTransport(), 10) { 100.0 }
        d.hover = true
        d.setSticks(0.0, 0.0, 0.5, 0.0)  // throttle 0.5*127 ≈ 63
        val p = d.packet()
        assertEquals(63, p[4].toInt() and 0xff)
    }

    @Test fun hoverReflectedInStatus() {
        val d = DroneEngine(RecordingTransport(), 10) { 100.0 }
        assertEquals(false, d.status()["hover_active"])
        d.hover = true
        assertEquals(true, d.status()["hover_active"])
    }

    @Test fun hoverUsesConfiguredThrottle() {
        val d = DroneEngine(RecordingTransport(), 10) { 100.0 }
        d.hover = true
        d.hoverThrottle = 80
        assertEquals(80, d.packet()[4].toInt() and 0xff)
    }

    @Test fun statusWireAxesReflectHoverThrottle() {
        val d = DroneEngine(RecordingTransport(), 10) { 100.0 }
        d.hover = true
        d.hoverThrottle = 70
        val s = d.status()
        assertEquals(listOf(128, 128, 70, 128), s["wire_axes"])
        assertEquals(70, s["hover_throttle"])
    }

    // ---- rx / auto-variant ----

    @Test fun rxAutoDetectGl() {
        val (d, t) = engine(null)  // auto
        t.cannedReceive = byteArrayOf(82, 0, 0, 0, 0, 0)
        d.handleReceive(byteArrayOf(82, 0, 0, 0, 0, 0))
        assertEquals(82, d.variant)
        assertEquals("GL(21B)", d.status()["variant"])
        assertEquals(1, d.rx)
    }

    @Test fun rxAutoDetectTc() {
        val (d, _) = engine(null)
        d.handleReceive(byteArrayOf(10, 0, 0, 0, 0, 0))
        assertEquals(10, d.variant)
        assertEquals("TC(9B)", d.status()["variant"])
        assertEquals(1, d.rx)
    }

    @Test fun statusShape() {
        val (d, _) = engine(10)
        val s = d.status()
        assertEquals(false, s["connected"])  // fresh engine, never connected
        assertEquals("TC(9B)", s["variant"])
        assertEquals(1, s["gear"])
        assertEquals(false, s["headless"])
        assertEquals(1, s["cam"])
        assertEquals(listOf(128, 128, 0, 128), s["axes"])
        assertEquals(0, s["sent"])
        assertEquals(0, s["rx"])
        assertEquals(null, s["last_telemetry"])
        assertEquals(false, s["trajectory_active"])
        assertEquals(0, s["trajectory_index"])
        assertEquals("rtsp://192.168.1.1:7070/webcam", s["rtsp"])
    }
}
